$checks=0;
function workflowCheck(bool $ok,string $message):void{global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$message);$checks++;}
function workflowReject(callable $operation,string $class,string $message):void{try{$operation();}catch(Throwable $error){workflowCheck($error instanceof $class,$message.' ('.$error::class.')');return;}throw new RuntimeException('FAIL: accepted '.$message);}
$db=TestSupport::db();$seeds=TestSupport::seed($db);Schema::install($db);$run='workflow-'.bin2hex(random_bytes(5));$access=[];
foreach($seeds as $role=>$seed){$id=$run.'-'.$role;Db::run($db,'INSERT INTO native_users(id,club_id,name) VALUES(?,?,?)',[$id,$role==='outsider'?$run.'-other':$run,'Synthetisch '.$role]);Db::run($db,'INSERT INTO native_grants(actor_id,module,capability) SELECT ?,module,capability FROM native_grants WHERE actor_id=?',[$id,$seed]);$access[$role]=new Access($db,$id);}
$pages=new Pages($db,$access['admin']);$articles=new Articles($db,$access['admin']);$editor=new Articles($db,$access['editor']);$reader=new Articles($db,$access['reader']);$outside=new Articles($db,$access['outsider']);
$root=dirname(__DIR__,2).'/.local/native-workflow-tests/'.$run;mkdir($root,0700,true);$media=new Media($db,$access['admin'],$root.'/media');$image=imagecreatetruecolor(20,20);imagepng($image,$root.'/synthetic.png');unset($image);$asset=$media->upload($root.'/synthetic.png','synthetic.png','Testbild');
$item=$articles->save(['title'=>'Öffentliche Musik','slug'=>'aktuelles/musik','news_date'=>'2026-10-08','excerpt'=>'Rückblick','body_html'=>'<p>Öffentlicher Stand</p>','media_ids'=>[$asset['id']]]);$item=$articles->publish($item['id'],1);
$item=$articles->save(['id'=>$item['id'],'title'=>'Unfertiger neuer Titel'],2);$before=$item;$generation=$pages->generation();
workflowCheck(!$item['archived']&&$item['archived_at']===null,'ordinary page has lifecycle metadata');
workflowReject(fn()=>$reader->archive($item['id'],3),DomainException::class,'reader cannot archive');
workflowReject(fn()=>$editor->archive($item['id'],3),DomainException::class,'archive requires publication right');
workflowReject(fn()=>$outside->archive($item['id'],3),RuntimeException::class,'cross-club archive denied');
workflowReject(fn()=>$articles->archive($item['id'],2),Conflict::class,'stale archive denied');
$archived=$articles->archive($item['id'],3);
workflowCheck($archived['archived']&&$archived['version']===4&&$archived['archived_at']!==null,'archive persists lifecycle and version');
workflowCheck($archived['title']===$before['title']&&$archived['body_html']===$before['body_html'],'archive preserves draft content');
workflowCheck($archived['published_revision']===null&&$articles->publicArticle('aktuelles/musik')===null&&$articles->publicCount()===0,'archive retracts public projection');
workflowCheck($media->publicVariant($asset['id'],'thumb')===null,'archive retracts public media reference');
workflowCheck($pages->generation()>$generation,'archive invalidates public cache');
workflowCheck(count($articles->list())===0&&count($articles->list('','archive'))===1&&count($articles->list('','all'))===1,'archive separate from active list');
workflowCheck($articles->revisions($item['id'])[0]['action']==='archive','archive audit');
workflowReject(fn()=>$pages->publish($item['id'],4),Conflict::class,'generic publisher cannot bypass archive');
workflowReject(fn()=>$articles->archive($item['id'],4),Conflict::class,'duplicate archive rejected');
$archived=$articles->save(['id'=>$item['id'],'archived'=>false,'title'=>'Archivierter Text bleibt archiviert'],4);
workflowCheck($archived['archived'],'save cannot spoof lifecycle');
$archived=$articles->restore($item['id'],1,5);workflowCheck($archived['archived']&&$archived['version']===6,'restoring content cannot unarchive');
workflowReject(fn()=>$reader->unarchive($item['id'],6),DomainException::class,'reader cannot return archive');
workflowReject(fn()=>$editor->unarchive($item['id'],5),Conflict::class,'stale unarchive denied');
$active=$editor->unarchive($item['id'],6);
workflowCheck(!$active['archived']&&$active['version']===7&&$active['published_revision']===null,'return to active keeps offline');
workflowCheck($articles->revisions($item['id'])[0]['action']==='unarchive','return audit');
workflowReject(fn()=>$editor->unarchive($item['id'],7),Conflict::class,'duplicate return rejected');
$active=$articles->publish($item['id'],7);workflowCheck($active['published_revision']===8,'explicit reapproval required');
$draft=$articles->save(['title'=>'Lesung 100%_ 😀','slug'=>'aktuelles/lesung','news_date'=>'2025-05-04','excerpt'=>'Find mich']);
workflowCheck(count($articles->list('musik','published'))===1,'case-insensitive typed news search');
workflowCheck(count($articles->list('100%_','draft'))===1&&count($articles->list("' OR 1=1 --"))===0,'search is literal, not SQL');
workflowCheck(count($articles->list('ÖFFENTLICHE'))===1,'Unicode case folding');
workflowCheck(count($articles->list('find mich'))===1,'excerpt search');
foreach(['bad','archived','published OR 1']as$status)workflowReject(fn()=>$articles->list('',$status),InvalidArgumentException::class,'unknown scope rejected');
foreach([str_repeat('a',121),"a\0b","a\nb"]as$q)workflowReject(fn()=>$articles->list($q),InvalidArgumentException::class,'unsafe/oversized search rejected');
workflowCheck($pages->search([['field'=>'title','op'=>'eq','value'=>$active['title']]])[0]['archived']===false,'selectors expose lifecycle');

$order=new AlbumOrder($db,$access['admin']);$gallery=new Gallery($db,$access['admin'],$root.'/media','workflow-csrf');$albumPages=[];
foreach(['Alpha','Beta','Gamma']as$n=>$title){$p=$pages->save(['title'=>$title,'slug'=>'galerie/'.strtolower($title),'template'=>'gallery','nav_visible'=>false,'nav_order'=>$n*10,'body_html'=>'<p>Öffentlich '.$title.'</p>','media_ids'=>[$asset['id']]]);$p=$pages->publish($p['id'],1);$albumPages[]=$p;}
$alpha=$albumPages[0];$beta=$albumPages[1];$gamma=$albumPages[2];$alphaDraft=$pages->save(array_replace($alpha,['title'=>'PRIVATE ALPHA','body_html'=>'<p>Privater Text</p>','nav_order'=>1000]),2);
$beforePayload=$pages->get($alpha['id']);$publicBefore=$pages->publicPage($alpha['slug']);$gen=$pages->generation();
workflowCheck($order->state()===['version'=>0,'ids'=>[]],'new ordering starts at version zero');
workflowReject(fn()=>(new AlbumOrder($db,$access['reader']))->move($beta['id'],'up',0),DomainException::class,'reader cannot sort');
workflowReject(fn()=>(new AlbumOrder($db,$access['editor']))->move($beta['id'],'up',0),DomainException::class,'editor cannot modify public sorting');
workflowReject(fn()=>(new AlbumOrder($db,$access['outsider']))->move($beta['id'],'up',0),DomainException::class,'other club cannot sort');
workflowReject(fn()=>$order->move($draft['id'],'up',0),DomainException::class,'only albums sortable');
workflowReject(fn()=>$order->move($beta['id'],'sideways',0),InvalidArgumentException::class,'sort direction restricted');
workflowCheck(array_column($gallery->albums(),'id')===array_column($albumPages,'id'),'draft position/title do not alter initial public ordering');
// Published values form the baseline; a pending draft position cannot leak through a move.
$baseline=array_column($gallery->albums(),'id');$target=$baseline[1];$state=$order->move($target,'up',0);
workflowCheck($state['version']===1&&$state['ids'][0]===$target,'move persists independent order');
workflowCheck($pages->get($alpha['id'])===$beforePayload,'ordering does not modify unrelated draft');
workflowCheck($pages->publicPage($alpha['slug'])===$publicBefore,'ordering does not replace published revision');
workflowCheck($pages->generation()===$gen+1,'ordering invalidates public cache');
workflowCheck(array_column($gallery->albums(),'id')===$state['ids'],'manager uses persisted order');
$html=$gallery->publicContent();$publishedNames=[];foreach($state['ids']as$id){foreach($albumPages as$p)if($p['id']===$id)$publishedNames[]=$p['title'];}
workflowCheck(strpos($html,'aria-label="'.$publishedNames[0].'"')<strpos($html,'aria-label="'.$publishedNames[1].'"'),'public display uses independent order');
workflowCheck(!str_contains($html,'PRIVATE ALPHA')&&!str_contains($html,'Privater Text'),'reorder does not leak draft');
workflowReject(fn()=>$order->move($target,'down',0),Conflict::class,'stale ordering rejected');
workflowCheck($order->move($target,'up',1)['version']===1,'boundary movement is no-op');
workflowCheck((int)Db::run($db,'SELECT COUNT(*) FROM khcms_album_order_revisions WHERE club_id=?',[$run])->fetchColumn()===1,'ordering has independent audit');
workflowCheck((new AlbumOrder($db,$access['outsider']))->state()['ids']===[],'ordering state isolated by club');
$gallery->action(['operation'=>'album-order','id'=>$target,'version'=>$pages->get($target)['version'],'direction'=>'down','order_version'=>1],[]);
workflowCheck($order->state()['version']===2,'HTTP action updates order state');
workflowReject(fn()=>$gallery->action(['operation'=>'album-order','id'=>$target,'version'=>$pages->get($target)['version'],'direction'=>'down','order_version'=>1],[]),Conflict::class,'HTTP order conflict');

$view=new ArticleView($db,$access['admin'],$root.'/media','workflow-csrf');$readerView=new ArticleView($db,$access['reader'],$root.'/media','workflow-csrf');
$html=$view->manager('',[]);workflowCheck(str_contains($html,'<table')&&!str_contains($html,'news-admin-list'),'news compact table');
workflowCheck(str_contains($html,'name="q"')&&str_contains($html,'name="status"')&&str_contains($html,'name="year"'),'news filter controls');
workflowCheck(str_contains($html,'value="news"')&&str_contains($html,'method="get"'),'news GET manager routing');
workflowCheck(str_contains($html,'article-archive'),'real archive action exposed');
$filtered=$view->manager('',['q'=>'Lesung','status'=>'draft','year'=>'2025']);workflowCheck(str_contains($filtered,'Lesung 100%_')&&!str_contains($filtered,'Öffentliche Musik'),'news filter changes result set');
workflowCheck(str_contains($view->manager('',['q'=>'<img src=x>']),'&lt;img src=x&gt;'),'search HTML escaping');
workflowReject(fn()=>$view->manager('',['q'=>[]]),InvalidArgumentException::class,'array query rejected');
workflowReject(fn()=>$view->manager('',['year'=>'2026 OR']),InvalidArgumentException::class,'malformed year rejected');
workflowCheck(!str_contains($readerView->manager('',[]),'article-archive'),'reader no archive action');
$view->action(['csrf'=>'workflow-csrf','operation'=>'article-archive','id'=>$draft['id'],'version'=>1]);
workflowCheck(str_contains($view->manager('',['status'=>'archive']),'Lesung 100%_')&&!str_contains($view->manager('',['status'=>'active']),'Lesung 100%_'),'archive tab reflects lifecycle');
workflowCheck(!str_contains($view->manager($draft['id'],[]),'value="article-publish"'),'archived editor cannot publish');
workflowCheck(str_contains($view->manager($draft['id'],[]),'Aus Archiv zurückholen'),'archived editor return action');
$view->action(['csrf'=>'workflow-csrf','operation'=>'article-unarchive','id'=>$draft['id'],'version'=>2]);
workflowReject(fn()=>$view->action(['csrf'=>'bad','operation'=>'article-archive','id'=>$draft['id'],'version'=>3]),DomainException::class,'archive action CSRF');
$html=$gallery->manager('',[]);workflowCheck(str_contains($html,'<table')&&!str_contains($html,'album-overview'),'gallery compact table');
workflowCheck(str_contains($html,'value="media"')&&str_contains($html,'name="q"'),'gallery GET routing and search');
workflowCheck(str_contains($html,'value="album-order"')&&str_contains($html,'name="order_version"'),'gallery actual ordering controls');
workflowCheck(!str_contains($gallery->manager('',['q'=>'Gamma']),'PRIVATE ALPHA'),'gallery search result set');
workflowReject(fn()=>$gallery->manager('',['q'=>[]]),InvalidArgumentException::class,'gallery array search rejected');
workflowReject(fn()=>$gallery->manager('',['status'=>'archive']),InvalidArgumentException::class,'gallery invalid status rejected');
workflowCheck(!str_contains((new Gallery($db,$access['reader'],$root.'/media'))->manager('',[]),'value="album-order"'),'reader no order controls');
workflowCheck(str_contains($gallery->manager($alpha['id'],[]),'data-album-upload'),'image editor preserved');
workflowCheck(str_contains($view->manager($active['id'],[]),'data-richtext'),'full article editor preserved');
class WorkflowBeforeTransactionPDO extends PDO {public ?Closure $before=null;public function beginTransaction():bool{if($this->before){$hook=$this->before;$this->before=null;$hook();}return parent::beginTransaction();}}
$config=TestSupport::config();$race=new WorkflowBeforeTransactionPDO('mysql:host=127.0.0.1;port=13371;dbname='.$config['database'].';charset=utf8mb4',$config['username'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
$raceAccess=new Access($race,$run.'-admin');$revoke=static fn()=>Db::run($db,"DELETE FROM native_grants WHERE actor_id=? AND module='website' AND capability='publish'",[$run.'-admin']);$grant=static fn()=>Db::run($db,"INSERT INTO native_grants(actor_id,module,capability) VALUES(?,'website','publish')",[$run.'-admin']);
$race->before=$revoke;workflowReject(fn()=>(new Pages($race,$raceAccess))->archive($active['id'],$active['version']),DomainException::class,'archive rechecks permission at transaction boundary');$grant();
workflowCheck(!$pages->get($active['id'])['archived'],'revoked archive rolled back');
$orderBefore=$order->state();$race->before=$revoke;workflowReject(fn()=>(new AlbumOrder($race,$raceAccess))->move($target,'up',$orderBefore['version']),DomainException::class,'ordering rechecks permission at transaction boundary');$grant();
workflowCheck($order->state()===$orderBefore,'revoked ordering rolled back');
$schedules=new PublicationSchedule($db,$access['admin']);
$planned=$articles->save(['title'=>'Geplanter Beitrag','slug'=>'aktuelles/geplant','news_date'=>'2026-10-08','body_html'=>'<p>Geprüfter Plantext</p>']);
$dueLocal=(new DateTimeImmutable('+1 day',new DateTimeZone('Europe/Berlin')))->setTime(12,0)->format('Y-m-d\TH:i');$dueAt=PublicationSchedule::parseBerlin($dueLocal);
$planPost=['csrf'=>'workflow-csrf','operation'=>'article-plan','id'=>$planned['id'],'version'=>1,'schedule_version'=>0,'publish_at'=>$dueLocal];
$view->action($planPost);$job=$schedules->forPage($planned['id']);
workflowCheck($job['status']==='pending'&&$job['page_version']===1&&$job['due_at']===$dueAt,'article adapter creates real scheduled job');
workflowCheck($articles->get($planned['id'])['version']===1&&$articles->publicArticle($planned['slug'])===null,'planning does not prematurely publish');
workflowCheck(str_contains($view->manager($planned['id'],[]),'Planung abbrechen')&&str_contains($view->manager($planned['id'],[]),'laufenden Veröffentlichungsdienst'),'editor exposes cancellation and worker condition');
workflowCheck(str_contains($view->manager('',['q'=>'Geplanter Beitrag']),'Geplant:'),'table displays real pending schedule');
workflowCheck(!str_contains($readerView->manager($planned['id'],[]),'value="article-plan"'),'reader sees status without planning controls');
workflowReject(fn()=>$view->action($planPost),Conflict::class,'repeated plan stale schedule version');
workflowReject(fn()=>$readerView->action($planPost),DomainException::class,'reader cannot plan');
workflowReject(fn()=>$view->action(array_replace($planPost,['csrf'=>'bad'])),DomainException::class,'planning adapter CSRF');
workflowReject(fn()=>$view->action(array_replace($planPost,['publish_at'=>[]])),InvalidArgumentException::class,'planning rejects array datetime');
workflowReject(fn()=>$view->action(array_replace($planPost,['publish_at'=>'2027-03-28T02:30'])),DomainException::class,'planning rejects DST spring gap');
workflowReject(fn()=>$view->action(array_replace($planPost,['publish_at'=>'2026-10-25T02:30'])),DomainException::class,'planning rejects ambiguous autumn time');
workflowReject(fn()=>$view->action(['csrf'=>'workflow-csrf','operation'=>'article-cancel-plan','id'=>$planned['id'],'version'=>1,'schedule_version'=>1,'schedule_id'=>str_repeat('a',32)]),Conflict::class,'cancellation tied to current page plan');
$view->action(['csrf'=>'workflow-csrf','operation'=>'article-cancel-plan','id'=>$planned['id'],'version'=>1,'schedule_version'=>1,'schedule_id'=>$job['id']]);
workflowCheck($schedules->forPage($planned['id'])['status']==='cancelled','cancellation is persisted');
$view->action($planPost);$planned=$articles->save(['id'=>$planned['id'],'body_html'=>'<p>Neu und ungeprüft</p>'],1);
workflowCheck(str_contains($view->manager($planned['id'],[]),'Entwurf geändert – Termin neu planen'),'changed draft warning before worker');
$albumNow=$pages->get($beta['id']);$albumBefore=$albumNow;
$gallery->action(['csrf'=>'workflow-csrf','operation'=>'album-plan','id'=>$beta['id'],'version'=>$albumNow['version'],'schedule_version'=>0,'publish_at'=>$dueLocal],[]);
workflowCheck($schedules->forPage($beta['id'])['status']==='pending','album adapter creates real plan');
workflowCheck(str_contains($gallery->manager($beta['id'],[]),'value="album-cancel-plan"'),'album editor cancellation control');
$os=$order->state();$ids=$os['ids'];$moveId=$ids[1];$order->move($moveId,'up',$os['version']);
workflowCheck($pages->get($beta['id'])===$albumBefore,'display reorder does not invalidate scheduled content');
$archivedPlan=$articles->save(['title'=>'Archivtermin','slug'=>'aktuelles/archivtermin','news_date'=>'2026-10-08']);
$schedules->plan($archivedPlan['id'],1,$dueAt);$articles->archive($archivedPlan['id'],1);
PublicationSchedule::runDue($db,null,500,$dueAt+1);
workflowCheck($schedules->forPage($planned['id'])['status']==='conflicted'&&$articles->publicArticle($planned['slug'])===null,'changed scheduled draft never publishes');
workflowCheck($schedules->forPage($beta['id'])['status']==='published'&&$pages->get($beta['id'])['version']===$albumBefore['version']+1,'album plan truly publishes unchanged version despite ordering');
workflowCheck($schedules->forPage($archivedPlan['id'])['status']==='conflicted'&&$articles->publicArticle($archivedPlan['slug'])===null,'archiving blocks pending publication');
$result=['suite'=>'native-content-workflow','passed'=>$checks,'fixture'=>'own model database, random club','external_requests'=>0];file_put_contents(dirname($root).'/result.json',json_encode($result,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));echo json_encode($result,JSON_PRETTY_PRINT).PHP_EOL;
